package com.nth.desktop3d;

import android.app.Instrumentation;
import android.view.View;
import android.view.ViewGroup;
import android.view.MotionEvent;
import android.os.SystemClock;
import android.widget.Button;
import android.widget.EditText;
import java.util.concurrent.atomic.AtomicReference;

/** Reproductions from the 0.7.2 phone checklist, using native input and actual state. */
public final class Polish073Smoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;
    public Polish073Smoke(Instrumentation test,MainActivity activity,String output){this.test=test;this.activity=activity;this.output=output;}
    public void run()throws Exception{
        invoke("showSettings",new Class[]{String.class},"folders");clickPrefix("Folder opening animation");int menu=new CrystalPreferences(activity).menuAnimation();click("3D Stack");
        check(store().preferences.getInt("folder_animation",-1)==3,"Folder animation was not saved independently");check(new CrystalPreferences(activity).menuAnimation()==menu,"Folder choice changed menu animation");
        Object preview=find(v->v instanceof SettingsPreview);check(preview!=null&&(Boolean)field(preview,"openingRunning"),"Folder preview did not animate");float before=(Float)field(preview,"openingProgress");idle(250);check((Float)field(preview,"openingProgress")>before,"Folder preview remained still");capture("folder-animation-preview");
        invoke("showSettings",new Class[]{String.class},"choice:menu_animation");click("Radial Arc");check(store().preferences.getInt("folder_animation",-1)==3,"Menu choice changed folder animation");preview=find(v->v instanceof SettingsPreview);check((Boolean)field(preview,"openingRunning"),"Menu preview did not animate");capture("menu-animation-preview");
        invoke("showSettings",new Class[]{String.class},"nota");check(find(v->v instanceof EditText&&"Search settings".contentEquals(v.getContentDescription()))==null,"Search settings remained on Nota page");check(find(v->"Command examples".contentEquals(v.getContentDescription()))!=null,"Nota examples menu missing");
        EditText question=(EditText)find(v->v instanceof EditText&&"Ask Nth Nota".contentEquals(v.getContentDescription()));check(question!=null&&question.getHint().toString().equals("(Write command or question here...)"),"Nota placeholder missing");
        int grid=store().preferences.getInt("grid_columns",4);main(()->question.setText("help"));click("Send to Nth Nota AI");check(store().preferences.getInt("grid_columns",4)==grid,"Vague request changed a setting");check(find(v->v instanceof Button&&"Home screen".contentEquals(((Button)v).getText()))!=null,"Vague request did not offer useful choices");
        click("Command examples");systemClick("open Home screen settings");check(question.getText().toString().equals("open Home screen settings"),"Example did not fill the request field");check("nota".equals(((SettingsStudio)field(activity,"settingsStudio")).page()),"Example was executed instead of inserted");
        test.getUiAutomation().executeShellCommand("settings put secure show_ime_with_hard_keyboard 1").close();int height=((View)find(v->v instanceof SettingsPreview)).getHeight();main(()->{question.requestFocus();((android.view.inputmethod.InputMethodManager)activity.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).showSoftInput(question,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});await(()->activity.getWindow().getDecorView().getRootWindowInsets().isVisible(android.view.WindowInsets.Type.ime()),"IME did not open");test.sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);await(()->!activity.getWindow().getDecorView().getRootWindowInsets().isVisible(android.view.WindowInsets.Type.ime()),"IME did not close");idle(400);check(find(v->v instanceof SettingsPreview).getHeight()==height,"Preview stayed shrunken after keyboard Back");capture("nota-keyboard-return");
        invoke("showSetup",new Class[]{int.class},1);test.getTargetContext().startActivity(new android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+activity.getPackageName())).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));idle(700);test.sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);await(()->field(activity,"setupGuide")!=null&&((SetupGuide)field(activity,"setupGuide")).step()==1,"Returning from Android skipped the media recovery step");check(find(v->v instanceof Button&&"Open App info".contentEquals(((Button)v).getText()))!=null,"App info recovery action was lost");capture("setup-media-return");
        invoke("closePanel",new Class[]{});
        LauncherStore.Item folder=new LauncherStore.Item("folder","Gesture folder");main(()->{store().page=store().pageCount()-1;store().pages.get(store().page).clear();folder.cellX=1;folder.cellY=3;store().pages.get(store().page).add(folder);store().save();desktop().rebuild();});idle(600);
        View tile=desktop().findViewWithTag("not-used");tile=cell(folder.id);int[] p=position(tile);swipe(p[0]+tile.getWidth()/2f,p[1]+tile.getHeight()/2f,0,-180,false,0);await(()->field(activity,"appsAdapter")!=null,"Swipe up starting on a folder did not open the drawer");
        View drawer=find(v->v instanceof SwipeDismissGrid);p=position(drawer);swipe(p[0]+drawer.getWidth()/2f,p[1]+Math.min(90,drawer.getHeight()/4),0,180,false,0);await(()->field(activity,"overlay")==null,"Pulling down at the top did not close the drawer");
        int count=store().pageCount(),from=store().page;tile=cell(folder.id);p=position(tile);swipe(p[0]+tile.getWidth()/2f,p[1]+tile.getHeight()/2f,activity.getWindow().getDecorView().getWidth()-4-(p[0]+tile.getWidth()/2f),0,true,1100);await(()->store().pageCount()==count+1&&store().page==count,"Holding a desktop folder at the edge did not create and open a desktop");check(!store().pages.get(from).contains(folder)&&store().pages.get(count).contains(folder),"Edge drop lost or duplicated the folder");capture("desktop-folder-edge-drop");
        main(()->{store().preferences.edit().putInt("gesture_two_up",3).apply();});int[] origin=position(desktop());twoFinger(origin[0]+20,origin[1]+220,origin[0]+desktop().getWidth()-20,origin[1]+220,-110);await(()->find(v->v instanceof Button&&"Internet".contentEquals(((Button)v).getText()))!=null,"Assigned two finger swipe did not open device controls");
        invoke("closePanel",new Class[]{});main(()->activity.gesture(5));if(!GestureAccess.available())check(field(activity,"setupGuide")!=null&&((SetupGuide)field(activity,"setupGuide")).step()==2,"Protected system action did not explain optional access");invoke("closePanel",new Class[]{});
    }
    private LauncherStore store(){return (LauncherStore)field(activity,"store");}private DesktopView desktop(){return (DesktopView)field(activity,"desktop");}
    @SuppressWarnings("unchecked") private View cell(String id){return ((java.util.Map<String,View>)field(desktop(),"cellViews")).get(id);}
    private void clickPrefix(String text){main(()->{View v=find(x->x instanceof Button&&((Button)x).getText().toString().startsWith(text));check(v!=null,"Missing control: "+text);v.performClick();});idle(100);}
    private void click(String text){main(()->{View v=find(x->text.contentEquals(x.getContentDescription())||(x instanceof Button&&(((Button)x).getText().toString().equals(text)||((Button)x).getText().toString().equals("✓  "+text))));check(v!=null,"Missing control: "+text);v.performClick();});idle(100);}
    private void systemClick(String text){long until=SystemClock.uptimeMillis()+5000;while(SystemClock.uptimeMillis()<until){android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)for(android.view.accessibility.AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text))if(text.contentEquals(n.getText())){android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);pointer(SystemClock.uptimeMillis(),0,r.centerX(),r.centerY());pointer(SystemClock.uptimeMillis(),1,r.centerX(),r.centerY());idle(200);return;}idle(100);}throw new AssertionError("Example row missing");}
    private int[] position(View view){check(view!=null,"Gesture target missing");AtomicReference<int[]> p=new AtomicReference<>();main(()->{int[] v=new int[2];view.getLocationOnScreen(v);p.set(v);});return p.get();}
    private void swipe(float x,float y,float dx,float dy,boolean hold,long edgeWait){long start=SystemClock.uptimeMillis();pointer(start,0,x,y);if(hold)idle(android.view.ViewConfiguration.getLongPressTimeout()+150);for(int i=1;i<=10;i++){pointer(start,2,x+dx*i/10,y+dy*i/10);idle(40);}if(edgeWait>0){idle(edgeWait);pointer(start,2,x+dx-70,y+dy);idle(80);}pointer(start,1,x+dx-(edgeWait>0?70:0),y+dy);idle(350);}
    private void pointer(long start,int action,float x,float y){MotionEvent event=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(event,true);event.recycle();}
    private void twoFinger(float x,float y,float x2,float y2,float dy){long start=SystemClock.uptimeMillis();pointer(start,0,x,y);multi(start,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),x,y,x2,y2);for(int i=1;i<=8;i++){multi(start,2,x,y+dy*i/8,x2,y2+dy*i/8);idle(40);}multi(start,MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),x,y+dy,x2,y2+dy);pointer(start,1,x,y+dy);idle(400);}
    private void multi(long start,int action,float x,float y,float x2,float y2){MotionEvent.PointerProperties[] pp={new MotionEvent.PointerProperties(),new MotionEvent.PointerProperties()};MotionEvent.PointerCoords[] cc={new MotionEvent.PointerCoords(),new MotionEvent.PointerCoords()};for(int i=0;i<2;i++){pp[i].id=i;pp[i].toolType=MotionEvent.TOOL_TYPE_FINGER;cc[i].x=i==0?x:x2;cc[i].y=i==0?y:y2;cc[i].pressure=cc[i].size=1;}MotionEvent event=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,2,pp,cc,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);test.getUiAutomation().injectInputEvent(event,true);event.recycle();}
    private interface Match{boolean matches(View v);}private View find(Match m){return find(activity.getWindow().getDecorView(),m);}private View find(View v,Match m){if(v.getVisibility()!=View.VISIBLE)return null;if(m.matches(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=find(((ViewGroup)v).getChildAt(i),m);if(found!=null)return found;}return null;}
    private Object field(Object target,String name){try{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(Exception e){throw new AssertionError(e);}}
    private void invoke(String name,Class<?>[] types,Object... args){main(()->{try{java.lang.reflect.Method method=MainActivity.class.getDeclaredMethod(name,types);method.setAccessible(true);method.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}});idle(200);}
    private void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{r.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void idle(long ms){SystemClock.sleep(ms);test.runOnMainSync(()->{});}private void await(java.util.function.BooleanSupplier ready,String message){long until=SystemClock.uptimeMillis()+7000;while(SystemClock.uptimeMillis()<until){AtomicReference<Boolean> r=new AtomicReference<>(false);main(()->r.set(ready.getAsBoolean()));if(r.get())return;idle(100);}throw new AssertionError(message);}
    private void capture(String name){android.graphics.Bitmap image=test.getUiAutomation().takeScreenshot();java.io.File dir=output==null?new java.io.File(test.getTargetContext().getExternalFilesDir(null),"verification"):new java.io.File(output);dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{image.recycle();}}
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
}
